# Manually fixed by Himja after the behaviour check failed 3 times: naive datetimes are now
# normalised to UTC *before* the comparison (the model compared naive with aware -> TypeError),
# and the unused pytz dependency was replaced by datetime.timezone.
from datetime import datetime, timezone


def incident_age_hours(occurred_at: datetime, now: datetime = None) -> float:
    """
    Returns the number of hours that have passed between occurred_at and now (default: the current UTC time).
    Naive datetimes are treated as UTC. Raises ValueError if occurred_at is later than now.
    """
    if now is None:
        now = datetime.now(timezone.utc)
    if occurred_at.tzinfo is None:          # manual fix: normalise before comparing
        occurred_at = occurred_at.replace(tzinfo=timezone.utc)
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)

    if occurred_at > now:
        raise ValueError("Occurred at datetime is later than now.")

    delta = now - occurred_at
    return delta.total_seconds() / 3600
